// Count how many emails already sent today per inbox
const sentToday = {};
const today = new Date().toISOString().split('T')[0];

// This node tracks daily limits — n8n processes items one at a time
// For a full implementation, read from the Sent Log sheet to count
// Here we use a simple counter stored in workflow static data

const MAX_PER_INBOX = 20;

const items = $input.all();
const outputItems = [];

for (const item of items) {
  const inbox = item.json['Assigned Inbox'] || 'inbox1';
  sentToday[inbox] = sentToday[inbox] || 0;

  if (sentToday[inbox] < MAX_PER_INBOX) {
    sentToday[inbox]++;
    outputItems.push(item);
  }
  // Leads over limit are skipped — they'll be picked up tomorrow
}

return outputItems;

// Read email templates from the Templates sheet
// and merge with lead data to build personalized emails

const items = $input.all();
const outputItems = [];

for (const item of items) {
  const lead = item.json;
  const clinicType = (lead['Clinic Type'] || 'dental').toLowerCase();
  const step = 'step1'; // This workflow handles Step 1 only

  // --- DENTAL STEP 1 TEMPLATE ---
  let subject = '';
  let body = '';

  if (clinicType === 'dental' || clinicType === 'orthodontics') {
    subject = `Quick question for ${lead['First Name'] || lead['Contact Name'] || 'there'}`;
    body = `Hi ${lead['First Name'] || 'there'},

I was looking at ${lead['Business Name']} on Google Maps and noticed ${lead['Personalization Tag'] || 'a few things worth discussing'} — I work with dental practices on exactly that.

I help small dental offices attract more local patients without spending money on ads — usually through optimizing their Google Business profile and getting a steady flow of patient referrals set up systematically.

Most practices I work with pick up 3–8 new patients/month within the first 60 days.

Would a 15-minute call this week make sense to see if it's a fit?

[YOUR NAME]
[YOUR TITLE]
[YOUR PHONE]

You're receiving this because your clinic appears in local search for ${lead['City']}, ${lead['State']}. Reply "unsubscribe" to opt out.`;
  } else {
    // Aesthetic / Med Spa
    subject = `Quick idea for ${lead['Business Name']}`;
    body = `Hi ${lead['First Name'] || 'there'},

I came across ${lead['Business Name']} while researching aesthetic clinics in ${lead['City']} — ${lead['Personalization Tag'] || 'thought this might be relevant'}.

I work with small med spas and aesthetic practices on client retention and new patient acquisition — without paid ads. Specifically: getting existing clients to come back more often and refer friends automatically.

The average practice I work with adds $3–5K/month in recurring revenue within 90 days just from retention fixes.

Would a quick 15-minute call make sense to see if there's a fit for your practice?

[YOUR NAME]
[YOUR TITLE]
[YOUR PHONE]

You're receiving this because your clinic appears in local search for ${lead['City']}, ${lead['State']}. Reply "unsubscribe" to opt out.`;
  }

  outputItems.push({
    json: {
      ...lead,
      emailSubject: subject,
      emailBody: body,
      step: 'step1'
    }
  });
}

return outputItems;

// Add a random delay between 3–8 minutes between emails
// to simulate human sending behavior

const items = $input.all();
const outputItems = [];

for (let i = 0; i < items.length; i++) {
  const delayMinutes = Math.floor(Math.random() * (8 - 3 + 1)) + 3;
  const delayMs = delayMinutes * 60 * 1000;

  outputItems.push({
    json: {
      ...items[i].json,
      delayMs: i === 0 ? 0 : delayMs, // First email sends immediately
      sendOrder: i + 1
    }
  });
}

return outputItems;

// Log the send to the Sent Log sheet
const item = $input.item.json;
const now = new Date().toISOString();

return [{
  json: {
    Timestamp: now,
    'Lead ID': item['Lead ID'],
    'Business Name': item['Business Name'],
    Email: item['Email'],
    Step: '1',
    'Inbox Used': item['Assigned Inbox'],
    Subject: item['emailSubject'],
    Status: 'sent'
  }
}];

// Update the lead's status and Step 1 sent date in Leads sheet
const item = $input.item.json;
const today = new Date().toISOString().split('T')[0];

// Calculate next action date (+3 days for Step 2)
const nextDate = new Date();
nextDate.setDate(nextDate.getDate() + 3);
const nextActionDate = nextDate.toISOString().split('T')[0];

return [{
  json: {
    'Lead ID': item['Lead ID'],
    Status: 'emailed-step1',
    'Step 1 Sent Date': today,
    'Next Action Date': nextActionDate
  }
}];
